/* Lesson data: KMP string matching (structure mode). Steps are generated by simulating the algorithm. */
(function () {
  var TEXT = 'ABABABACABA', PAT = 'ABABAC';
  var X0 = 70, DX = 76, TY = 95, PY = 170;
  function lpsOf(p) {
    var l = [0], k = 0;
    for (var i = 1; i < p.length; i++) {
      while (k && p[i] !== p[k]) k = l[k - 1];
      if (p[i] === p[k]) k++;
      l.push(k);
    }
    return l;
  }
  var LPS = lpsOf(PAT);

  function lpsScene() {
    var ops = [], steps = [];
    for (var i = 0; i < PAT.length; i++) ops.push(['node', 'p' + i, PAT[i], X0 + i * DX, 110, 'cell']);
    steps.push({ pl: 0, cl: 0, h: 380, say: 'KMP never moves backwards in the text. It needs a table first: lps[i] = the length of the longest proper prefix of the pattern that is ALSO a suffix of pattern[0..i]. It tells us how much of the match we can keep after a mismatch.', csay: 'Build the lps table.', ds: ops });
    var lps = [0], k = 0;
    steps.push({ pl: 1, cl: 1, h: 380, say: 'lps[0] = 0: a single character has no proper prefix. k is the length of the current matched prefix.', csay: 'lps[0] = 0; k = 0.', ds: [['note', 'p0', 'lps=0'], ['ptr', 'k', 'p0', 'up']] });
    for (var i2 = 1; i2 < PAT.length; i2++) {
      steps.push({ pl: 2, cl: 2, h: 380, say: 'i = ' + i2 + ': compare pattern[' + i2 + '] = ' + PAT[i2] + ' with pattern[k] = ' + PAT[k] + '.', csay: 'i = ' + i2, ds: [['ptr', 'i', 'p' + i2, 'up'], ['ptr', 'k', 'p' + k, 'up'], ['hot', 'p' + i2, 'p' + k]] });
      while (k && PAT[i2] !== PAT[k]) {
        var nk = lps[k - 1];
        steps.push({ pl: 3, cl: 3, h: 380, say: PAT[i2] + ' differs from ' + PAT[k] + '. Fall back: k = lps[' + (k - 1) + '] = ' + nk + ' (the next-longest prefix that is also a suffix).', csay: 'k = lps[k - 1];', ds: [['ptr', 'k', 'p' + nk, 'up'], ['hot', 'p' + nk]] });
        k = nk;
      }
      var ops2 = [];
      if (PAT[i2] === PAT[k]) {
        k++;
        steps.push({ pl: 4, cl: 4, h: 380, say: 'They match, so the prefix grows: k = ' + k + '.', csay: 'k++;', ds: [['hot', 'p' + i2, 'p' + (k - 1)]] });
      } else steps.push({ pl: 4, cl: 4, h: 380, say: 'No match even at k = 0, so the prefix length stays 0.', csay: 'No match.', ds: [] });
      lps.push(k);
      steps.push({ pl: 5, cl: 5, h: 380, say: 'lps[' + i2 + '] = ' + k + '.' + (k ? ' The first ' + k + ' characters equal the last ' + k + ' characters of pattern[0..' + i2 + '].' : ''), csay: 'lps[i] = k;', ds: [['note', 'p' + i2, 'lps=' + k]] });
    }
    steps.push({ pl: 6, cl: 6, h: 380, say: 'The table is ' + JSON.stringify(lps).replace(/,/g, ', ') + '. Each step either grows k or shrinks it, and k can only shrink as often as it grew, so building is O(m).', csay: 'return lps;', ds: [['unptr', 'i'], ['unptr', 'k']] });
    return steps;
  }

  function searchScene() {
    var ops = [], steps = [], tags = [];
    for (var t = 0; t < TEXT.length; t++) ops.push(['node', 't' + t, TEXT[t], X0 + t * DX, TY, 'cell']);
    for (var q = 0; q < PAT.length; q++) ops.push(['node', 'p' + q, PAT[q], X0 + q * DX, PY, 'cell']);
    steps.push({ pl: 0, cl: 0, h: 380, say: 'Search "' + PAT + '" in "' + TEXT + '". The pattern row slides along the text. The lps table is ' + JSON.stringify(LPS).replace(/,/g, ', ') + ' (from the previous scene). The text pointer i only ever moves right.', csay: 'Search with the lps table.', ds: ops });
    var j = 0, shift = 0, found = false;
    function place(newShift) {
      var o = [];
      if (newShift !== shift) { for (var q2 = 0; q2 < PAT.length; q2++) o.push(['mv', 'p' + q2, X0 + (q2 + newShift) * DX, PY]); shift = newShift; }
      return o;
    }
    function clearTags() { var o = tags.map(function (e) { return ['untag', e[0], e[1]]; }); tags = []; return o; }
    function addTag(id, c, o) { o.push(['tag', id, c]); tags.push([id, c]); }
    steps.push({ pl: 2, cl: 2, h: 380, say: 'Start with j = 0 (nothing matched yet).', csay: 'j = 0;', ds: [['ptr', 'j', 'p0', 'down']] });
    for (var i = 0; i < TEXT.length && !found; i++) {
      var ch = TEXT[i];
      while (j && ch !== PAT[j]) {
        var o1 = clearTags();
        for (var m = 0; m < j; m++) { addTag('t' + (i - j + m), 'done', o1); addTag('p' + m, 'done', o1); }
        addTag('t' + i, 'bad', o1); addTag('p' + j, 'bad', o1);
        o1.push(['ptr', 'i', 't' + i, 'up'], ['ptr', 'j', 'p' + j, 'down']);
        steps.push({ pl: 3, cl: 3, h: 380, say: 'Mismatch: text ' + ch + ' vs pattern ' + PAT[j] + ' after matching ' + j + ' characters. Do NOT restart: the table says the last ' + LPS[j - 1] + ' matched characters are also a prefix of the pattern.', csay: 'Mismatch.', ds: o1 });
        var nj = LPS[j - 1];
        var o2 = clearTags();
        o2 = o2.concat(place(i - nj));
        for (var m2 = 0; m2 < nj; m2++) { addTag('t' + (i - nj + m2), 'done', o2); addTag('p' + m2, 'done', o2); }
        o2.push(['ptr', 'i', 't' + i, 'up'], ['ptr', 'j', 'p' + nj, 'down']);
        steps.push({ pl: 3, cl: 3, h: 380, say: 'Slide the pattern right so its first ' + nj + ' characters sit over those matched text characters: j = lps[' + (j - 1) + '] = ' + nj + '. The text pointer i stays at ' + i + '.', csay: 'j = lps[j - 1];', ds: o2 });
        j = nj;
      }
      var o3 = clearTags();
      for (var m3 = 0; m3 < j; m3++) { addTag('t' + (i - j + m3), 'done', o3); addTag('p' + m3, 'done', o3); }
      o3.push(['ptr', 'i', 't' + i, 'up'], ['ptr', 'j', 'p' + j, 'down']);
      if (ch === PAT[j]) {
        addTag('t' + i, 'hot', o3); addTag('p' + j, 'hot', o3);
        j++;
        steps.push({ pl: 4, cl: 4, h: 380, say: 'Text ' + ch + ' equals pattern ' + PAT[j - 1] + ': j becomes ' + j + '.', csay: 'j++;', ds: o3 });
      } else {
        addTag('t' + i, 'bad', o3);
        steps.push({ pl: 4, cl: 4, h: 380, say: 'Text ' + ch + ' does not match ' + PAT[j] + ' and nothing is matched yet (j = 0): just move on.', csay: 'No match, i++.', ds: o3 });
      }
      if (j === PAT.length) {
        var o4 = clearTags();
        for (var m4 = 0; m4 < PAT.length; m4++) { addTag('t' + (i - PAT.length + 1 + m4), 'done', o4); addTag('p' + m4, 'done', o4); }
        steps.push({ pl: 5, cl: 5, h: 380, say: 'j = ' + PAT.length + ': the whole pattern matched, starting at text index ' + (i - j + 1) + '. i never went backwards, so the search was O(n + m).', csay: 'return i - j + 1;', ds: o4 });
        found = true;
      }
    }
    return steps;
  }

  var PY_LPS = ['def build_lps(p):', '    lps = [0] * len(p); k = 0', '    for i in range(1, len(p)):', '        while k and p[i] != p[k]: k = lps[k - 1]', '        if p[i] == p[k]: k += 1', '        lps[i] = k', '    return lps'];
  var C_LPS = ['void build_lps(const char *p, int m, int *lps) {', '    lps[0] = 0; int k = 0;', '    for (int i = 1; i < m; i++) {', '        while (k && p[i] != p[k]) k = lps[k - 1];', '        if (p[i] == p[k]) k++;', '        lps[i] = k;', '    }}'];
  var PY_S = ['def kmp_search(text, pat):', '    lps = build_lps(pat)', '    j = 0                          # characters matched so far', '    for i, ch in enumerate(text):', '        while j and ch != pat[j]: j = lps[j - 1]', '        if ch == pat[j]: j += 1', '        if j == len(pat): return i - j + 1', '    return -1'];
  var C_S = ['int kmp_search(const char *t, const char *p) {', '    int n = strlen(t), m = strlen(p), lps[M]; build_lps(p, m, lps);', '    int j = 0;                       /* characters matched so far */', '    for (int i = 0; i < n; i++) {', '        while (j && t[i] != p[j]) j = lps[j - 1];', '        if (t[i] == p[j]) j++;', '        if (j == m) return i - j + 1;', '    } return -1; }'];

  window.LESSON = {
    id: 'kmp',
    mode: 'ds',
    title: 'KMP string matching',
    lede:
      'The naive search restarts the comparison after every mismatch and costs O(n x m). Knuth-Morris-Pratt keeps what it has already matched. A pre-computed table says, for each prefix of the pattern, how long its longest border is (a prefix that is also a suffix). On a mismatch the pattern slides by exactly the amount that border allows, and the text pointer never moves backwards. Total cost O(n + m).',
    scenes: [
      { id: 'lps', title: 'The lps table', blurb: 'For every prefix of the pattern: the longest proper prefix that is also a suffix.', trap: 'Confusing lps[i] (length of a border of pattern[0..i]) with a position. On a mismatch you use lps[j - 1], the border of the part already matched, not lps[j]. Off-by-one here is the most common KMP bug.', pyCode: PY_LPS, cCode: C_LPS, predict: { q: 'What is lps for the pattern "ABAB"?', options: ['[0, 0, 1, 2]', '[0, 1, 2, 3]', '[0, 0, 0, 0]'], answer: 0, why: '"A" has no border; "AB" none; "ABA" has "A"; "ABAB" has "AB". So 0, 0, 1, 2.' }, steps: lpsScene() },
      { id: 'search', title: 'Searching with the table', blurb: 'The text pointer only moves right; on a mismatch the pattern row slides, not the text.', trap: 'Resetting i backwards after a mismatch (i = i - j + 1) is the naive algorithm in disguise. In KMP only j changes on a mismatch. Also check j == len(pattern) right after incrementing, before reading pattern[j] again.', pyCode: PY_S, cCode: C_S, predict: { q: 'On a mismatch with j characters already matched, what does KMP do?', options: ['Restart with j = 0 and i = i - j + 1', 'Set j = lps[j - 1] and keep i where it is', 'Skip the whole pattern length'], answer: 1, why: 'The border says how many of the matched characters are still valid, so no text character is re-read.' }, steps: searchScene() },
    ],
    builtins: [
      ['text.find(pat)', 'Python substring search. CPython uses an optimised mix of algorithms (not plain KMP) and is usually fastest.'],
      ['pat in text', 'Boolean version of the same search.'],
      ['strstr(text, pat)', 'C standard library substring search; often a fast but implementation-specific algorithm.'],
      ['re.search(pat, text)', 'Regular expressions when the pattern is not fixed text.'],
      ['str.startswith / endswith', 'Prefix and suffix checks; the idea behind borders.'],
      ['text.count(pat)', 'Non-overlapping occurrences; use KMP when you need overlapping ones.'],
    ],
  };
})();
